import{_t as e,it as t,n,rt as r}from"./chunks/framework.BIpRff3v.js";var i=JSON.parse(`{"title":"Review gates and dispositions","description":"","frontmatter":{},"headers":[],"relativePath":"pipeline-review.md","filePath":"pipeline-review.md"}`),a={name:`pipeline-review.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="review-gates-and-dispositions" tabindex="-1" dir="auto">Review gates and dispositions <a class="header-anchor" href="#review-gates-and-dispositions" aria-label="Permalink to “Review gates and dispositions”">​</a></h1><h2 id="review-gates-and-dispositions-1" tabindex="-1" dir="auto">Review gates and dispositions <a class="header-anchor" href="#review-gates-and-dispositions-1" aria-label="Permalink to “Review gates and dispositions”">​</a></h2><p dir="auto">CI, the review threads and the Copilot review (when <a href="#copilot-review-is-optional"><code>REQUIRE_COPILOT</code></a> is on) are <strong>required gates on the PR&#39;s head commit</strong>. Every review thread is either resolved or explicitly dispositioned by the repo owner, and one commit status, <strong><code>pipeline/gates</code></strong>, sums it all up for that exact SHA. The main ruleset requires it, pinned to the pipeline App (<code>tools/scripts/pipeline/setup-ruleset.sh</code>). This is a two-week trial.</p><h3 id="the-gates" tabindex="-1" dir="auto">The gates <a class="header-anchor" href="#the-gates" aria-label="Permalink to “The gates”">​</a></h3><p dir="auto"><code>pipeline/gates</code> is set by the pipeline App (<code>approval.yml</code>, <code>approval</code> command; pure logic in <code>evaluateGates</code>). For the current head all of these must hold, checked in this order:</p><ol><li dir="auto"><strong>CI</strong>: the <code>ci</code> check run succeeded (and the <code>security</code> CI job, if it ran).</li><li dir="auto"><strong>Review threads</strong>: no unresolved thread.</li><li dir="auto"><strong>Copilot</strong>: it reviewed this head. Only when <code>REQUIRE_COPILOT</code> is <code>true</code>; otherwise this gate is <code>success</code> with the detail &quot;not required (REQUIRE_COPILOT off)&quot;.</li><li dir="auto"><strong><code>pipeline/protected-approval</code></strong>: a pipeline PR that touches protected paths needs the owner&#39;s approval of this exact head (status <code>success</code>, recomputed by the <code>approval</code> command, not just read back). A PR with no protected paths, and any PR the pipeline did not open, gets <code>success</code> automatically. See <a href="./pipeline-protected-changes.html#protected-change-approval">Protected-change approval</a>.</li></ol><p dir="auto">The status is <code>success</code> when all hold, <code>failure</code> for a real blocker (CI failed, a required approval was refused) and <code>pending</code> otherwise, its description naming the first missing gate. A push gives the new SHA no status, which blocks the merge; <code>approval.yml</code> posts a <code>pending</code> one as soon as CI is requested so the PR says why it waits. When the gates hold, the existing hand-off happens: <code>stage:human-approval</code>, PR marked ready (only a PR the pipeline opened as a draft; a person&#39;s own draft stays a draft), code owners requested. Merging stays with a human.</p><h3 id="copilot-review-is-optional" tabindex="-1" dir="auto">Copilot review is optional <a class="header-anchor" href="#copilot-review-is-optional" aria-label="Permalink to “Copilot review is optional”">​</a></h3><p dir="auto">The Copilot review needs a Copilot licence, so it is <strong>off by default</strong>. The repo variable <code>REQUIRE_COPILOT</code> turns it on, and only the exact string <code>true</code> does: unset, empty, <code>false</code>, <code>TRUE</code>, <code>1</code> or anything else is off (a typo can never leave <code>pipeline/gates</code> pending forever for a review nobody licensed).</p><ul><li dir="auto"><strong>Off:</strong> the <code>copilot</code> gate is <code>success</code> (&quot;not required (REQUIRE_COPILOT off)&quot;), no review is requested (so <code>copilot_request_failed</code> cannot happen) and the PR goes to <code>stage:human-approval</code> as soon as the other gates hold. The state table shows &quot;not required&quot;. If Copilot reviews anyway, its threads still count as review threads.</li><li dir="auto"><strong>On:</strong> the review is requested once per head commit after CI and threads hold, and the hand-off waits until Copilot reviewed that commit.</li><li dir="auto"><strong>To turn it on:</strong> set the variable <code>REQUIRE_COPILOT</code> to <code>true</code>, and either give the secret <code>COPILOT_REVIEW_TOKEN</code> the token of a Copilot-licensed user or enable automatic Copilot review for the repo, and enable Copilot code review (Settings → Copilot → Code review).</li></ul><p dir="auto"><strong>Why one status:</strong> the ruleset can only require named checks. Requiring CI, Copilot and thread resolution separately would need a status for each and would not express &quot;resolved <em>or</em> dispositioned&quot;. One bot-set status bound to the SHA, computed by tested code, is the single thing to require. Only the App can set it (the ruleset pins its integration id). GitHub has no workflow trigger for resolving a thread by hand: resolve through <code>/disposition</code>, or re-run <strong>Pipeline · Approval</strong> (Actions → run workflow, PR number) after resolving one manually.</p><p dir="auto">The bot keeps one <strong>Review gates</strong> comment per PR (<code>&lt;!-- pipeline:gates --&gt;</code>, edited in place): each gate, the open Copilot threads with their ids, and the dispositions on record.</p><h3 id="thread-ids" tabindex="-1" dir="auto">Thread ids <a class="header-anchor" href="#thread-ids" aria-label="Permalink to “Thread ids”">​</a></h3><p dir="auto">Copilot threads: <code>C-&lt;n&gt;</code>, <code>n</code> = database id of the thread&#39;s top comment, listed in the Review gates comment.</p><h3 id="disposition-owner-only" tabindex="-1" dir="auto"><code>/disposition</code> (owner only) <a class="header-anchor" href="#disposition-owner-only" aria-label="Permalink to “/disposition (owner only)”">​</a></h3><p dir="auto">Three ways to post it, all the owner&#39;s <strong>new</strong> comments (never an edit):</p><ol><li dir="auto"><p dir="auto"><strong>A top-level PR comment</strong> whose body is one or more lines of exactly</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/disposition &lt;finding-id&gt; &lt;accepted-risk|false-positive|out-of-scope&gt; &lt;reason, at least 10 characters&gt;</span></span></code></pre></div></li><li dir="auto"><p dir="auto"><strong>A quote reply.</strong> GitHub&#39;s &quot;Quote reply&quot; puts the quoted text (<code>&gt; ...</code> lines) first. A quote block at the top of the body, and blank lines, are ignored; the command follows it. A quote in the middle or at the end is not.</p></li><li dir="auto"><p dir="auto"><strong>A reply inside the finding&#39;s own review thread</strong> (a Copilot thread). The short form leaves the id out, because the thread names it: <code>/disposition &lt;kind&gt; &lt;reason&gt;</code>. The long form works too, but its id must be the thread&#39;s. One command per reply. In a thread that is not a finding thread the command is refused. The bot answers in the thread (<code>Recorded: see &lt;link&gt;</code> or the <code>Not recorded: ...</code> reason) and writes the record note in the PR conversation, where <code>approval.yml</code> reads it.</p></li></ol><p dir="auto">The only comment that does not count is an edit of an existing one.</p><ul><li dir="auto">Every line must be valid, or the comment is rejected as a whole with one short bot reply giving the reason. Prose around the command is a rejection. A comment where <code>/disposition</code> starts a line but something other than a quote block comes before it is answered with &quot;the command must be the first thing in the comment ... Post it again as a new comment&quot;, never silence. A mention in backticks or in the middle of a sentence is ordinary discussion and is ignored.</li><li dir="auto">Accepted only from <code>vars.PIPELINE_OWNER_LOGIN</code> and only from a <code>User</code> account. Not <code>author_association</code>, not the PR author. Unset variable: nobody. Others&#39; comments are ignored without a reply. Same-repo branches only.</li><li dir="auto">The id must be an open Copilot thread on the PR.</li><li dir="auto">On acceptance the bot resolves the finding&#39;s review thread (so the ruleset&#39;s thread-resolution requirement is met), then appends one record note per finding: <code>&lt;!-- pipeline:disposition id=… kind=… head=&lt;sha&gt; by=&lt;login&gt; comment=&lt;id&gt; --&gt;</code> with the reason in a fenced block. The notes re-run <code>approval.yml</code>.</li></ul><h3 id="what-a-disposition-records" tabindex="-1" dir="auto">What a disposition records <a class="header-anchor" href="#what-a-disposition-records" aria-label="Permalink to “What a disposition records”">​</a></h3><p dir="auto">A record names the head the owner saw and the thread id (<code>C-&lt;n&gt;</code>). Accepting it resolves that thread, so the gates stop counting it; the record stays on the PR and the Review gates comment lists it with the owner&#39;s reason. Only records made by the owner count, and only the bot&#39;s own notes are read.</p>`,21)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};